out = ["%=====================================================================",
       "\\section*{Bibliographie vérifiée}\\addcontentsline{toc}{section}{Bibliographie vérifiée}",
       "Chaque référence a été cherchée en ligne le 23 novembre 2026. \\emph{Mode} : source de la vérification (Crossref par DOI ou recherche bibliographique ; interface d'arXiv ; OpenLibrary pour les livres sans DOI ; page de l'éditeur ; Wikisource). « Résumé lu » : le résumé a été lu en ligne ; sinon seule l'existence et les métadonnées sont vérifiées. \\emph{Cité par} : A = Argon, C = Carbon, N = Neon, n = la présente note. Les métadonnées (volume, pages) sont celles des réponses des services, non des PDF.",
       "{\\footnotesize\\renewcommand{\\arraystretch}{1.1}",
       "\\begin{longtable}{@{}>{\\raggedright\\arraybackslash}p{8.7cm}>{\\raggedright\\arraybackslash}p{3.6cm}>{\\raggedright\\arraybackslash}p{2.1cm}>{\\raggedright\\arraybackslash}p{0.9cm}@{}}",
       "\\toprule \\textbf{Référence} & \\textbf{Identifiant} & \\textbf{Mode} & \\textbf{Cité par}\\\\ \\midrule\\endhead \\bottomrule\\endfoot"]
for c, i, m, w in R:
    parts = []
    for part in i.split(" ; "):
        raw = part.replace("\\_", "_")
        if raw.startswith(("doi:", "arXiv:", "proceedings.")):
            parts.append("\\nolinkurl{" + raw + "}")
        else:
            parts.append(part)
    ident = " ; ".join(parts)
    out.append(f"{c} & {ident} & {m} & {w}\\\\")
out += ["\\end{longtable}}", ""]
open(sys.argv[1], "w").write("\n".join(out))
print(len(R), "références ;", sum(1 for r in R if "vérifier" in r[2]), "à vérifier")
